"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["911738"],{295293(e){e.exports=JSON.parse('{"tag":{"label":"filter","permalink":"/sdk/4.12.2/tags/filter","allTagsPath":"/sdk/4.12.2/tags","count":4,"items":[{"id":"guides/assessment-guide","title":"Assessment & Survey Guide","description":"Guide for creating ServiceNow Assessments and Surveys (asmtmetrictype) using the Fluent API. Surveys collect user feedback through simple, unscored questionnaires; assessments evaluate, score, and rank assessable records with weighted and normalized results. Both share the same nested structure: type \u2192 categories \u2192 metrics \u2192 definitions. This framework only defines the survey/assessment and its in-platform delivery (a generated instance in the recipient\'s assessment queue) \u2014 it does not email a survey link or send a notification, so to send, email, or notify a recipient you must pair it with an Email Notification.","permalink":"/sdk/4.12.2/guides/assessment-guide"},{"id":"api/table/columns/conditionscolumn-api","title":"ConditionsColumn","description":"A Column for a conditions type field.","permalink":"/sdk/4.12.2/api/table/columns/conditionscolumn-api"},{"id":"guides/dashboard-filters-guide","title":"Dashboard Filters","description":"Interactive filter widgets (filter, filter-group) for a Platform Analytics Dashboard() (par_dashboard, short for Performance Analytics Report), and how they drive the other widgets on a dashboard. For the base Dashboard/DashboardWidget config schema and every other widget type, see the dashboard-guide topic -- this guide picks up where that one hands off filter-specific detail.","permalink":"/sdk/4.12.2/guides/dashboard-filters-guide"},{"id":"guides/encoded-query-guide","title":"Encoded Queries","description":"How to build well-formed ServiceNow encoded query strings \u2014 the compact field-operator-value syntax used by most condition and filter fields across the Fluent APIs (Business Rules, ACLs, SLAs, Data Policies, UI Policies, Email Notifications, Flow triggers, and more) and by now-sdk query --query.","permalink":"/sdk/4.12.2/guides/encoded-query-guide"}],"unlisted":false}}')}}]);